pub(super)fn received_environment_with_memory(f:Arc<Fixture>,main:Chat,owner:Arc<Owned>,provider:&'static str,url:String,revoke_before_child:bool,selected_own:bool)->Arc<dyn Environment>{Arc::new(IterationEnv{f,main,owner,provider,url,child_started:AtomicBool::new(false),child_claimed:AtomicBool::new(false),child_finished:AtomicBool::new(false),revoke_before_child,received:true,selected_own})}
impl IterationEnv{
 fn child(&self){
  assert_eq!(self.owner.workers(),0);assert!(self.owner.waiting_for_resource());let pet=if self.provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"};let a=Authority::existing(&self.f.root.join("authority")).unwrap();let inbox=a.message_inbox(pet,None,8,crate::assistant_memory::now()).unwrap();let r=&inbox.items.iter().find(|i|i.receipt.envelope().schema_version==if self.received{16}else{14}).unwrap().receipt;let payload=r.envelope().delegation.as_ref().unwrap();
  assert_eq!(r.envelope().planned_data.as_ref().unwrap().source.references.len(),if self.received&&!self.selected_own{0}else{1});
  let frame=crate::settings::review::Frame::fixture();let review=DataReview::prepare_funded_at(&self.f.root.join("authority"),&self.f.catalog(),caller_in(pet,frame.clone()),ReceivedReference::from_receipt(r).unwrap(),"own-memory-derived-child".into(),payload.subgoal.clone(),payload.criteria.clone(),crate::assistant_memory::now()).unwrap();let ack=native_data_confirm(&self.f,review,frame);let g=ack.goal.clone();assert_eq!(g.schema_version,if self.received{60}else{57});assert!(g.spec.received_from.as_ref().unwrap().body.planned_dependencies.is_some());
  let(binding,c)=crate::pet_runtime::context::prepare_selected_data_fixture(&self.f.contexts(),&g,&self.main,None,&self.f.catalog(),&self.f.root.join("authority"),false).unwrap();drop(c);let g=native(&self.f).mutate(&g.id,pet,&g.revision,"literal-child-context".into(),Action::BindContext{binding},crate::assistant_memory::now()).unwrap().record;
  let g=native(&self.f).mutate(&g.id,pet,&g.revision,"literal-child-task".into(),Action::ProposeTask{description:"Own deterministic reply".into()},crate::assistant_memory::now()).unwrap().record;
  let g=native(&self.f).mutate(&g.id,pet,&g.revision,"literal-child-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:vec![StepInput{description:"One independently reviewed reply".into(),postcondition:"Native local receipt only".into(),operation:Some(OperationProposal{operation_id:"pet.reply".into(),version:2,arguments:json!({"toPetId":r.envelope().origin.pet_id,"source":ReceivedReference::from_receipt(r).unwrap(),"text":"Independent literal reply; parent success remains unverified","expiresAt":r.envelope().deadline_at})})}]},crate::assistant_memory::now()).unwrap().record;
  let cap=Budget{deadline_at:r.envelope().deadline_at,max_model_calls:0,max_tool_calls:1,max_output_bytes:16384,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly};let review=Review::prepare_deterministic(&g,native_evidence(&g),cap,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now()).unwrap();let approved=review.approve(&g,native_evidence(&g),crate::assistant_memory::now()).unwrap();let cert=a.certify(&approved,&g,crate::assistant_memory::now()).unwrap();let q=native(&self.f).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;
  let p=Controller::new().unwrap().prepare_memory_fixture(&q,&self.f.root.join("authority"),&self.f.contexts(),&self.f.catalog(),&self.main,&native_evidence(&q),nonce().unwrap(),crate::assistant_memory::now(),Arc::new(|_,_,_|Validity::Current)).unwrap();let(leased,o)=p.claim(&native(&self.f),&a,&native_evidence(&q),crate::assistant_memory::now()).unwrap();let o=Arc::new(o.unwrap());assert!(o.lease().model.is_empty());
  self.child_claimed.store(true,Ordering::Release);
  if self.revoke_before_child{if self.selected_own{let mut catalogue:Value=serde_json::from_slice(&fs::read(self.f.catalog()).unwrap()).unwrap();let items=catalogue["items"].as_array_mut().unwrap();items.retain(|n|n["id"]!="recipient-own-note");assert!(items.iter().any(|n|n["id"]=="selected-source-note"));catalogue["generation"]=json!(catalogue["generation"].as_u64().unwrap()+1);fs::write(self.f.catalog(),serde_json::to_vec(&catalogue).unwrap()).unwrap();}else{fs::write(self.f.catalog(),serde_json::to_vec(&json!({"version":1,"generation":2,"items":[]})).unwrap()).unwrap();}}
  if self.revoke_before_child{ack.assert_preserved(&self.f);}
  let driver=Driver::new(o.clone(),Arc::new(native(&self.f)),Arc::new(LiteralEnv));let outcome=driver.and_then(drive);let latest=native(&self.f).read(&leased.record.id,pet).unwrap();
  if self.revoke_before_child{assert!(outcome.is_err()||latest.state!=State::Completed);assert!(latest.completion.is_none());let grant:Value=serde_json::from_slice(&fs::read(self.f.root.join("authority").join(format!("{}.json",latest.admissions[0].spec.decision_id))).unwrap()).unwrap();assert!(grant["body"]["messages"].is_null());assert_eq!(o.workers(),0);let drain=o.drain(crate::pet_runtime::leases::DrainOutcome::Confirmed).unwrap();native(&self.f).drain_owned(&a,&drain,crate::assistant_memory::now()).unwrap();}
  else{assert_eq!(outcome.unwrap().phase,Phase::Completed);assert_eq!(latest.state,State::Completed);assert!(latest.completion.is_some());}
  self.child_finished.store(true,Ordering::Release);
 }
}
impl Environment for IterationEnv{
 fn capture(&self,_:&Owned)->model::Result<Capture>{Ok(Capture{configuration:configuration(),server:crate::local_chat::Server{id:self.provider,name:"Own memory iteration fixture",url:self.url.clone(),key:None},app:None})}
 fn configuration(&self)->model::Result<crate::pet_config::Configuration>{Ok(configuration())}
 fn peer_configuration(&self)->model::Result<(crate::pet_config::Configuration,crate::settings::Settings)>{Ok((configuration(),settings()))}
 fn target(&self)->model::Result<Arc<crate::spotify::goal::Target>>{panic!("No hardware/media effects")}
 fn notify(&self,s:&Status){if s.phase==Phase::WaitingPeers&&!self.child_started.swap(true,Ordering::AcqRel){self.child();}}
 fn decide(&self,s:Source)->Option<Decision>{
  assert!(s.current());let review=s.review();if s.target().origin==crate::pet_runtime::recipe_decisions::Origin::GoalPeerData{let text=review["data"]["actualRequestBody"]["messages"].to_string();if self.received{assert!(text.contains("DERIVED_APPROVED_TEXT_ONLY"));assert!(!text.contains("PRIVATE_GOAL_MEMORY_SENTINEL"));assert_eq!(text.contains("PRIVATE_RECIPIENT_OWN_NOTE"),self.selected_own);}else{assert!(text.contains("PRIVATE_GOAL_MEMORY_SENTINEL"));}assert!(text.contains("ownDelegatedOutcomeMetadata"));assert!(!text.contains("Independent literal reply"));assert_eq!(review["data"]["newBudgetGranted"],false);}
  else{let e=&review["recipe"]["steps"][0]["envelope"];assert!(if self.received{matches!(e["schemaVersion"].as_u64(),Some(15|16))}else{matches!(e["schemaVersion"].as_u64(),Some(13|14))});assert_eq!(e["plannedData"]["source"]["references"].as_array().unwrap().len(),if self.received&&!self.selected_own{0}else{1});}
  let f=crate::cli_chat::goal_decision_fixture(s);f.panel_answer(true,f.request["goalTarget"].clone()).unwrap();f.decision()
 }
}
fn recipient(f:&Fixture,a:&Authority,main:&Chat,r:&Receipt,revoke:bool){
 let own=selected(f,main,r);assert_eq!(own.schema_version,56);let provider=if own.spec.owner.pet_id=="ai_ollama"{"ollama"}else{"lmstudio"};let path=f.catalog();
 let(mut server,http)=idle_http(vec![("application/json",meta(provider).to_string()),("text/event-stream",stream("Own independently authorized interpretation, not verified completion",true))],move|route|{if revoke&&!route.contains("chat/completions"){fs::write(&path,serde_json::to_vec(&json!({"version":1,"generation":2,"items":[]})).unwrap()).unwrap();}});server.id=provider;
 let(g,o)=admit(f,a,&own,&server,main);let d=Driver::new(o.clone(),Arc::new(native(f)),Arc::new(Env{server:Some(server),revoke:None,choice:false})).unwrap();let result=drive(d);let requests=http.join().unwrap();let current=native(f).read(&g.id,&g.spec.owner.pet_id).unwrap();assert!(current.completion.is_none());assert_eq!(o.workers(),0);
 if revoke{assert!(result.is_err()||result.as_ref().unwrap().phase==Phase::RecoveryRequired);assert_eq!(requests.len(),1);assert!(requests.iter().all(|(route,_)|!route.contains("chat/completions")));return;}
 assert_eq!(result.unwrap().phase,Phase::AwaitingVerification);assert_eq!(requests.len(),2);let body=&requests[1].1;let text=body["messages"].to_string();assert!(text.contains("MEMORY_DERIVED_AFTER_CHILD")&&text.contains("receivedPlannedPeerMemoryData"));for private in ["PRIVATE_GOAL_MEMORY_SENTINEL","iteration-own-secret",r.envelope().origin.lease_id.as_str(),r.envelope().origin.controller_id.as_str()]{assert!(!text.contains(private),"Private source escaped native projection");}
 let grant:Value=serde_json::from_slice(&fs::read(f.root.join("authority").join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap()).unwrap();assert_eq!(grant["body"]["budgetUsage"]["attempts"][0]["inputHash"],model::fingerprint(&(&o.lease().id,"fixture-free",body)).unwrap());assert_eq!(grant["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),1);
}
fn exercise(provider:&'static str,revoke_before_child:bool,revoke_recipient:bool){
 let f=Arc::new(Fixture::new());let main=f.main();let deadline=crate::assistant_memory::now()+90_000;let pet=crate::pet_config::pet_id(provider).unwrap();let to=if provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"};let mut spec=Fixture::goal(Context::Unbound).spec;spec.owner=Owner{pet_id:pet.into(),provider:provider.into(),adapter:provider.into(),model_hint:Some("fixture-free".into())};f.write(vec![Fixture::record("iteration-own-secret",pet,None)]);let g=native_or_ensure(&f).create(spec,crate::assistant_memory::now()).unwrap().record;let(binding,c)=f.prepare(&g,&main,Mode::Dedicated,Some(&[Fixture::selected("iteration-own-secret")])).unwrap();drop(c);let g=native_or_ensure(&f).mutate(&g.id,pet,&g.revision,"iteration-memory-context".into(),Action::BindContext{binding},crate::assistant_memory::now()).unwrap().record;
 let first=json!({"kind":"plan","description":"Ask independent specialist using reviewed derived text","steps":[{"description":"Fund one literal response","postcondition":"Local receipt never parent completion","operation":{"operationId":"pet.delegate","version":1,"arguments":{"toPetId":to,"subgoal":"Own memory-derived literal work","criteria":[NATIVE_MESSAGE_CRITERION],"expiresAt":deadline,"allowance":{"modelCalls":0,"toolCalls":1,"outputBytes":16384},"maxDepth":2}}}]});
 let second=json!({"kind":"plan","description":"Derive one request after exact own context and peer DATA","steps":[{"description":"Share reviewed derived text","postcondition":"Local receipt only","operation":{"operationId":"pet.message","version":1,"arguments":{"toPetId":to,"kind":"request","text":"MEMORY_DERIVED_AFTER_CHILD","expiresAt":deadline}}}]});let mut replies=vec![("application/json",meta(provider).to_string()),("text/event-stream",stream(&first.to_string(),true))];if !revoke_before_child{replies.extend([("application/json",meta(provider).to_string()),("text/event-stream",stream(&second.to_string(),true))]);}let(mut server,http)=idle_http(replies,|_|{});server.id=provider;
 let mut cap=budget(deadline,8);cap.max_model_calls=4;let review=Review::prepare_planning_catalog(&g,evidence(&f,&g,&server),cap.clone(),Limits{max_rounds:2,max_steps:2,max_output_bytes:2048,no_progress_limit:2},&configuration(),Catalog::PeerDelegationIterationV1,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now()).unwrap();let approved=review.approve_with_data(&g,evidence(&f,&g,&server),Some(crate::pet_memory::context_model::GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap();let a=Authority::ensure(&f.root.join("authority")).unwrap();let cert=a.certify(&approved,&g,crate::assistant_memory::now()).unwrap();let q=native(&f).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;
 let p=Controller::new().unwrap().prepare_memory_fixture(&q,&f.root.join("authority"),&f.contexts(),&f.catalog(),&main,&evidence(&f,&q,&server),nonce().unwrap(),crate::assistant_memory::now(),Arc::new(|_,_,_|Validity::Current)).unwrap();let(leased,o)=p.claim(&native(&f),&a,&evidence(&f,&q,&server),crate::assistant_memory::now()).unwrap();let o=Arc::new(o.unwrap());let env=Arc::new(IterationEnv{f:f.clone(),main,owner:o.clone(),provider,url:server.url.clone(),child_started:AtomicBool::new(false),child_claimed:AtomicBool::new(false),child_finished:AtomicBool::new(false),revoke_before_child,received:false,selected_own:false});let d=Driver::new(o,Arc::new(native(&f)),env.clone()).unwrap();let result=drive(d);let requests=http.join().unwrap();let current=native(&f).read(&leased.record.id,pet).unwrap();assert!(current.completion.is_none());assert!(env.child_started.load(Ordering::Acquire));assert!(env.child_claimed.load(Ordering::Acquire),"child never reached claim");assert!(env.child_finished.load(Ordering::Acquire),"child callback did not finish; worker panic is not a refusal proof");assert_eq!(requests.len(),if revoke_before_child{2}else{4},"driver outcome: {result:?}");assert!(requests[1].1["messages"].to_string().contains("PRIVATE_GOAL_MEMORY_SENTINEL"));
 if revoke_before_child{assert!(result.is_err()||current.state!=State::Completed);return;}
 assert_eq!(result.unwrap().phase,Phase::AwaitingVerification);let grant:Value=serde_json::from_slice(&fs::read(f.root.join("authority").join(format!("{}.json",current.admissions[0].spec.decision_id))).unwrap()).unwrap();let body=&grant["body"];assert_eq!(body["schemaVersion"],45);assert_eq!(body["delegationPool"],serde_json::to_value(cap).unwrap());assert_eq!(body["planningUsage"]["rounds"].as_array().unwrap().len(),2);assert_eq!(body["messages"]["entries"].as_array().unwrap().len(),2);
 let inbox=a.message_inbox(to,None,8,crate::assistant_memory::now()).unwrap();let r=&inbox.items.iter().find(|i|i.receipt.envelope().schema_version==13).unwrap().receipt;let p=r.envelope().planned_data.as_ref().unwrap();assert_eq!(p.schema_version,3);assert!(p.round_data.is_some());assert_eq!(p.source.references[0].id,"iteration-own-secret");assert!(!p.model_metadata().to_string().contains("iteration-own-secret"));assert!(!r.envelope().provider_use_authorized);recipient(&f,&a,&env.main,r,revoke_recipient);
}
